1	import type { SupabaseClient } from '@supabase/supabase-js';
2	import type { ReceiptRow } from '$lib/models/Receipt';
3	import type { TransactionRow } from '$lib/models/Transaction';
4	import { resolveMatchingTolerances } from '$lib/models/Reconciliation';
5	import type {
6		ReconciliationResult,
7		ReconciliationOptions,
8		ReconciliationStats,
9		MatchedPair,
10		MatchConfidence,
11		MatchingTolerances,
12		UnmatchedReceipt,
13		UnmatchedTransaction,
14		ReconciliationDisplayRow,
15		ReconciliationSort,
16		ManualMatchRequest
17	} from '$lib/models/Reconciliation';
18	import { withRetry } from '$lib/utils/retry';
19	
20	const MS_PER_DAY = 1000 * 60 * 60 * 24;
21	
22	// CAD scoring: an amount difference below this counts as "exact to the cent"
23	const EXACT_AMOUNT_DIFF = 0.01;
24	
25	// #{#fcr3a} Foreign currency confidence bands (relative difference of converted amount)
26	const FC_HIGH_CONFIDENCE_PERCENT = 0.02;
27	const FC_MEDIUM_CONFIDENCE_PERCENT = 0.03;
28	
29	// Score weights (higher score = better candidate)
30	const SCORE_AMOUNT_EXACT = 10;
31	const SCORE_AMOUNT_CLOSE = 6;
32	const SCORE_AMOUNT_NEAR = 3;
33	const SCORE_SAME_DAY = 10;
34	const SCORE_ONE_DAY_APART = 5;
35	const SCORE_WITHIN_RANGE = 2;
36	
37	type ScoredCandidate = {
38		confidence: MatchConfidence;
39		score: number;
40	};
41	
42	type MatchingOutcome = {
43		matched: MatchedPair[];
44		unmatchedReceipts: UnmatchedReceipt[];
45		unmatchedTransactions: UnmatchedTransaction[];
46	};
47	
48	/**
49	 * Service for reconciling receipts with credit card/bank transactions
50	 *
51	 * Matching rules:
52	 * - Amounts must be the same (within tolerance)
53	 * - Dates must be within 3 days of each other
54	 * - Vendor names are ignored (they're inconsistent)
55	 */
56	export class ReconciliationService {
57		private supabase: SupabaseClient;
58	
59		constructor(supabase: SupabaseClient) {
60			this.supabase = supabase;
61		}
62	
63		/**
64		 * Performs automatic matching of receipts and transactions within a date range
65		 */
66		async reconcile(familyId: string, options: ReconciliationOptions): Promise<ReconciliationResult> {
67			return withRetry(async () => {
68				const tolerances = resolveMatchingTolerances(options);
69	
70				const allReceipts = await this.fetchReceiptsInRange(familyId, options);
71				const allTransactions = await this.fetchTransactionsInRange(familyId, options);
72	
73				const { alreadyMatchedReceipts, unmatchedReceipts, matchableTransactions } =
74					this.partitionForMatching(allReceipts, allTransactions, options.includeManuallMatched);
75	
76				const matchResult = this.performMatching(
77					unmatchedReceipts,
78					matchableTransactions,
79					tolerances
80				);
81	
82				const matchedPairs: MatchedPair[] = [
83					...matchResult.matched,
84					...this.buildManualMatchPairs(alreadyMatchedReceipts, allTransactions)
85				];
86	
87				// Excluded transactions are still shown in the UI, just never matched
88				const allUnmatchedTransactions: UnmatchedTransaction[] = [
89					...matchResult.unmatchedTransactions,
90					...this.buildExcludedUnmatchedTransactions(allTransactions)
91				];
92	
93				return {
94					matched: matchedPairs,
95					unmatchedReceipts: matchResult.unmatchedReceipts,
96					unmatchedTransactions: allUnmatchedTransactions,
97					stats: this.computeStats(allReceipts, allTransactions, matchedPairs, matchResult)
98				};
99			});
100		}
101	
102		private async fetchReceiptsInRange(
103			familyId: string,
104			options: ReconciliationOptions
105		): Promise<ReceiptRow[]> {
106			const { data, error } = await this.supabase
107				.from('receipts')
108				.select('*')
109				.eq('family_id', familyId)
110				.gte('transaction_date', options.startDate)
111				.lte('transaction_date', options.endDate)
112				.not('transaction_date', 'is', null)
113				.not('total_amount', 'is', null);
114	
115			if (error) throw error;
116			return (data as ReceiptRow[]) || [];
117		}
118	
119		private async fetchTransactionsInRange(
120			familyId: string,
121			options: ReconciliationOptions
122		): Promise<TransactionRow[]> {
123			// Includes excluded transactions so they stay visible in the UI
124			const { data, error } = await this.supabase
125				.from('transactions')
126				.select('*')
127				.eq('family_id', familyId)
128				.gte('transaction_date', options.startDate)
129				.lte('transaction_date', options.endDate);
130	
131			if (error) throw error;
132			return (data as TransactionRow[]) || [];
133		}
134	
135		/**
136		 * Splits the fetched rows into manual matches (kept as-is) and the pools
137		 * available to the automatic matching algorithm
138		 */
139		private partitionForMatching(
140			allReceipts: ReceiptRow[],
141			allTransactions: TransactionRow[],
142			includeManuallyMatched: boolean | undefined
143		): {
144			alreadyMatchedReceipts: ReceiptRow[];
145			unmatchedReceipts: ReceiptRow[];
146			matchableTransactions: TransactionRow[];
147		} {
148			const alreadyMatchedReceipts = includeManuallyMatched
149				? allReceipts.filter((r) => r.matched_transaction_id !== null)
150				: [];
151	
152			const unmatchedReceipts = allReceipts.filter((r) => r.matched_transaction_id === null);
153	
154			const alreadyMatchedTransactionIds = new Set(
155				alreadyMatchedReceipts
156					.map((r) => r.matched_transaction_id)
157					.filter((id): id is string => id !== null)
158			);
159	
160			// Excluded transactions are still shown in UI but not available for matching
161			const matchableTransactions = allTransactions.filter(
162				(t) => !alreadyMatchedTransactionIds.has(t.id) && !t.excluded
163			);
164	
165			return { alreadyMatchedReceipts, unmatchedReceipts, matchableTransactions };
166		}
167	
168		private buildManualMatchPairs(
169			alreadyMatchedReceipts: ReceiptRow[],
170			allTransactions: TransactionRow[]
171		): MatchedPair[] {
172			const pairs: MatchedPair[] = [];
173	
174			for (const receipt of alreadyMatchedReceipts) {
175				const transaction = allTransactions.find((t) => t.id === receipt.matched_transaction_id);
176				if (!transaction) continue;
177	
178				pairs.push({
179					receipt,
180					transaction,
181					matchConfidence: 'high' // Manual matches are high confidence
182				});
183			}
184	
185			return pairs;
186		}
187	
188		private buildExcludedUnmatchedTransactions(
189			allTransactions: TransactionRow[]
190		): UnmatchedTransaction[] {
191			return allTransactions
192				.filter((t) => t.excluded)
193				.map((transaction) => ({
194					transaction,
195					potentialMatches: [] // Excluded transactions don't get potential matches
196				}));
197		}
198	
199		private computeStats(
200			allReceipts: ReceiptRow[],
201			allTransactions: TransactionRow[],
202			matchedPairs: MatchedPair[],
203			matchResult: MatchingOutcome
204		): ReconciliationStats {
205			// Excluded transactions don't count toward totals
206			const nonExcludedTransactionCount = allTransactions.filter((t) => !t.excluded).length;
207	
208			return {
209				totalReceipts: allReceipts.length,
210				totalTransactions: nonExcludedTransactionCount,
211				matchedCount: matchedPairs.length,
212				unmatchedReceiptCount: matchResult.unmatchedReceipts.length,
213				unmatchedTransactionCount: matchResult.unmatchedTransactions.length,
214				matchRate:
215					allReceipts.length > 0 ? Math.round((matchedPairs.length / allReceipts.length) * 100) : 0
216			};
217		}
218	
219		/**
220		 * Core matching algorithm
221		 * Returns matched pairs and unmatched items
222		 */
223		private performMatching(
224			receipts: ReceiptRow[],
225			transactions: TransactionRow[],
226			tolerances: MatchingTolerances
227		): MatchingOutcome {
228			const matched = this.matchBestAvailablePairs(receipts, transactions, tolerances);
229	
230			const usedReceiptIds = new Set(matched.map((pair) => pair.receipt.id));
231			const usedTransactionIds = new Set(matched.map((pair) => pair.transaction.id));
232	
233			return {
234				matched,
235				unmatchedReceipts: this.buildUnmatchedReceipts(
236					receipts,
237					transactions,
238					usedReceiptIds,
239					usedTransactionIds,
240					tolerances
241				),
242				unmatchedTransactions: this.buildUnmatchedTransactions(
243					receipts,
244					transactions,
245					usedReceiptIds,
246					usedTransactionIds,
247					tolerances
248				)
249			};
250		}
251	
252		/**
253		 * Greedily pairs each receipt (in order) with its best still-available transaction
254		 */
255		private matchBestAvailablePairs(
256			receipts: ReceiptRow[],
257			transactions: TransactionRow[],
258			tolerances: MatchingTolerances
259		): MatchedPair[] {
260			const matched: MatchedPair[] = [];
261			const usedTransactionIds = new Set<string>();
262	
263			for (const receipt of receipts) {
264				const availableMatches = this.findPotentialMatches(receipt, transactions, tolerances).filter(
265					(pm) => !usedTransactionIds.has(pm.transaction.id)
266				);
267	
268				if (availableMatches.length === 0) continue;
269	
270				// Take the best match (first one, as they're sorted by confidence)
271				const bestMatch = availableMatches[0];
272				matched.push({
273					receipt,
274					transaction: bestMatch.transaction,
275					matchConfidence: bestMatch.confidence
276				});
277				usedTransactionIds.add(bestMatch.transaction.id);
278			}
279	
280			return matched;
281		}
282	
283		private buildUnmatchedReceipts(
284			receipts: ReceiptRow[],
285			transactions: TransactionRow[],
286			usedReceiptIds: Set<string>,
287			usedTransactionIds: Set<string>,
288			tolerances: MatchingTolerances
289		): UnmatchedReceipt[] {
290			return receipts
291				.filter((r) => !usedReceiptIds.has(r.id))
292				.map((receipt) => ({
293					receipt,
294					potentialMatches: this.findPotentialMatches(receipt, transactions, tolerances)
295						.filter((pm) => !usedTransactionIds.has(pm.transaction.id))
296						.map((pm) => pm.transaction)
297				}));
298		}
299	
300		private buildUnmatchedTransactions(
301			receipts: ReceiptRow[],
302			transactions: TransactionRow[],
303			usedReceiptIds: Set<string>,
304			usedTransactionIds: Set<string>,
305			tolerances: MatchingTolerances
306		): UnmatchedTransaction[] {
307			return transactions
308				.filter((t) => !usedTransactionIds.has(t.id))
309				.map((transaction) => ({
310					transaction,
311					potentialMatches: this.findPotentialMatchesForTransaction(transaction, receipts, tolerances)
312						.filter((pm) => !usedReceiptIds.has(pm.receipt.id))
313						.map((pm) => pm.receipt)
314				}));
315		}
316	
317		/**
318		 * Finds potential transaction matches for a given receipt, best first
319		 */
320		private findPotentialMatches(
321			receipt: ReceiptRow,
322			transactions: TransactionRow[],
323			tolerances: MatchingTolerances
324		): Array<{ transaction: TransactionRow; confidence: MatchConfidence }> {
325			const scored: Array<{ transaction: TransactionRow } & ScoredCandidate> = [];
326	
327			for (const transaction of transactions) {
328				const candidate = this.scoreCandidate(receipt, transaction, tolerances);
329				if (candidate) scored.push({ transaction, ...candidate });
330			}
331	
332			scored.sort((a, b) => b.score - a.score);
333			return scored.map(({ transaction, confidence }) => ({ transaction, confidence }));
334		}
335	
336		/**
337		 * Finds potential receipt matches for a given transaction, best first
338		 */
339		private findPotentialMatchesForTransaction(
340			transaction: TransactionRow,
341			receipts: ReceiptRow[],
342			tolerances: MatchingTolerances
343		): Array<{ receipt: ReceiptRow; confidence: MatchConfidence }> {
344			const scored: Array<{ receipt: ReceiptRow } & ScoredCandidate> = [];
345	
346			for (const receipt of receipts) {
347				const candidate = this.scoreCandidate(receipt, transaction, tolerances);
348				if (candidate) scored.push({ receipt, ...candidate });
349			}
350	
351			scored.sort((a, b) => b.score - a.score);
352			return scored.map(({ receipt, confidence }) => ({ receipt, confidence }));
353		}
354	
355		/**
356		 * Shared matching predicate: scores a receipt/transaction pair, or returns
357		 * null when the pair is outside the amount/date tolerances (no match)
358		 */
359		private scoreCandidate(
360			receipt: ReceiptRow,
361			transaction: TransactionRow,
362			tolerances: MatchingTolerances
363		): ScoredCandidate | null {
364			if (!receipt.total_amount || !receipt.transaction_date) return null;
365	
366			// #{#fcr3a} Foreign currency receipts are converted to CAD using the rate
367			// stored on the receipt, and compared with a percentage tolerance
368			const isForeignCurrency = receipt.currency !== null && receipt.currency !== 'CAD';
369			if (isForeignCurrency && !receipt.exchange_rate_to_cad) {
370				return null; // No exchange rate stored — cannot match this receipt
371			}
372	
373			const rawReceiptAmount = Math.abs(receipt.total_amount);
374			const receiptAmountCAD =
375				isForeignCurrency && receipt.exchange_rate_to_cad
376					? rawReceiptAmount * receipt.exchange_rate_to_cad
377					: rawReceiptAmount;
378	
379			const transactionAmount = Math.abs(transaction.amount);
380			const amountDiff = Math.abs(receiptAmountCAD - transactionAmount);
381			const percentDiff = transactionAmount > 0 ? amountDiff / transactionAmount : 1;
382	
383			const withinAmountTolerance = isForeignCurrency
384				? percentDiff <= tolerances.foreignCurrencyTolerancePercent
385				: amountDiff <= tolerances.amountTolerance;
386			if (!withinAmountTolerance) return null;
387	
388			const daysDiff = Math.abs(
389				(new Date(receipt.transaction_date).getTime() -
390					new Date(transaction.transaction_date).getTime()) /
391					MS_PER_DAY
392			);
393			if (daysDiff > tolerances.maxDaysDifference) return null;
394	
395			return isForeignCurrency
396				? this.scoreForeignCurrencyCandidate(percentDiff, daysDiff)
397				: this.scoreCadCandidate(amountDiff, daysDiff);
398		}
399	
400		/**
401		 * #{#fcr3a} Foreign currency confidence based on percentage difference
402		 */
403		private scoreForeignCurrencyCandidate(percentDiff: number, daysDiff: number): ScoredCandidate {
404			let score: number;
405			if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) score = SCORE_AMOUNT_EXACT;
406			else if (percentDiff <= FC_MEDIUM_CONFIDENCE_PERCENT) score = SCORE_AMOUNT_CLOSE;
407			else score = SCORE_AMOUNT_NEAR;
408	
409			let confidence: MatchConfidence = 'low';
410			if (daysDiff === 0) {
411				score += SCORE_SAME_DAY;
412				if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) confidence = 'high';
413				else if (percentDiff <= FC_MEDIUM_CONFIDENCE_PERCENT) confidence = 'medium';
414			} else if (daysDiff <= 1) {
415				score += SCORE_ONE_DAY_APART;
416				if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) confidence = 'medium';
417			} else {
418				score += SCORE_WITHIN_RANGE;
419			}
420	
421			return { score, confidence };
422		}
423	
424		/**
425		 * CAD confidence based on date proximity, with a bonus for exact amounts
426		 */
427		private scoreCadCandidate(amountDiff: number, daysDiff: number): ScoredCandidate {
428			let score = amountDiff < EXACT_AMOUNT_DIFF ? SCORE_AMOUNT_EXACT : 0;
429	
430			let confidence: MatchConfidence;
431			if (daysDiff === 0) {
432				score += SCORE_SAME_DAY;
433				confidence = 'high';
434			} else if (daysDiff <= 1) {
435				score += SCORE_ONE_DAY_APART;
436				confidence = 'medium';
437			} else {
438				score += SCORE_WITHIN_RANGE;
439				confidence = 'low';
440			}
441	
442			return { score, confidence };
443		}
444	
445		/**
446		 * Manually match a receipt to a transaction
447		 */
448		async manualMatch(request: ManualMatchRequest): Promise<ReceiptRow> {
449			return withRetry(async () => {
450				const { data, error } = await this.supabase
451					.from('receipts')
452					.update({ matched_transaction_id: request.transactionId })
453					.eq('id', request.receiptId)
454					.select('*')
455					.single();
456	
457				if (error) throw error;
458				return data as ReceiptRow;
459			});
460		}
461	
462		/**
463		 * Manually unmatch a receipt from its transaction
464		 */
465		async manualUnmatch(receiptId: string): Promise<ReceiptRow> {
466			return withRetry(async () => {
467				const { data, error } = await this.supabase
468					.from('receipts')
469					.update({ matched_transaction_id: null })
470					.eq('id', receiptId)
471					.select('*')
472					.single();
473	
474				if (error) throw error;
475				return data as ReceiptRow;
476			});
477		}
478	
479		/**
480		 * Converts reconciliation result to display rows for the UI table
481		 */
482		convertToDisplayRows(
483			result: ReconciliationResult,
484			sort?: ReconciliationSort
485		): ReconciliationDisplayRow[] {
486			const rows: ReconciliationDisplayRow[] = [];
487	
488			// #{#fcr5b} Helper to compute converted CAD amount from receipt's stored rate
489			const getConvertedCAD = (receipt: ReceiptRow | null): number | null => {
490				if (!receipt || !receipt.total_amount) return null;
491				if (!receipt.currency || receipt.currency === 'CAD') return null;
492				if (!receipt.exchange_rate_to_cad) return null;
493				return receipt.total_amount * receipt.exchange_rate_to_cad;
494			};
495	
496			// Add matched pairs (green rows at top)
497			for (const pair of result.matched) {
498				rows.push({
499					id: `matched-${pair.receipt.id}-${pair.transaction.id}`,
500					type: 'matched',
501					receipt: pair.receipt,
502					transaction: pair.transaction,
503					date: pair.receipt.transaction_date,
504					vendor: pair.receipt.merchant_name || pair.transaction.vendor_name,
505					amount: pair.receipt.total_amount,
506					creditCard: pair.transaction.credit_card_type,
507					matchConfidence: pair.matchConfidence,
508					convertedAmountCAD: getConvertedCAD(pair.receipt)
509				});
510			}
511	
512			// Add unmatched receipts
513			for (const unmatched of result.unmatchedReceipts) {
514				rows.push({
515					id: `receipt-${unmatched.receipt.id}`,
516					type: 'unmatchedReceipt',
517					receipt: unmatched.receipt,
518					transaction: null,
519					date: unmatched.receipt.transaction_date,
520					vendor: unmatched.receipt.merchant_name,
521					amount: unmatched.receipt.total_amount,
522					creditCard: unmatched.receipt.credit_card_name,
523					convertedAmountCAD: getConvertedCAD(unmatched.receipt)
524				});
525			}
526	
527			// Add unmatched transactions
528			for (const unmatched of result.unmatchedTransactions) {
529				rows.push({
530					id: `transaction-${unmatched.transaction.id}`,
531					type: 'unmatchedTransaction',
532					receipt: null,
533					transaction: unmatched.transaction,
534					date: unmatched.transaction.transaction_date,
535					vendor: unmatched.transaction.vendor_name,
536					amount: unmatched.transaction.amount,
537					creditCard: unmatched.transaction.credit_card_type,
538					convertedAmountCAD: null
539				});
540			}
541	
542			// Apply sorting if specified
543			if (sort) {
544				return this.sortDisplayRows(rows, sort);
545			}
546	
547			return rows;
548		}
549	
550		/**
551		 * Sorts display rows by the specified field and direction
552		 */
553		private sortDisplayRows(
554			rows: ReconciliationDisplayRow[],
555			sort: ReconciliationSort
556		): ReconciliationDisplayRow[] {
557			const sortedRows = [...rows];
558			const direction = sort.direction === 'asc' ? 1 : -1;
559	
560			sortedRows.sort((a, b) => {
561				let aVal: string | number;
562				let bVal: string | number;
563	
564				switch (sort.field) {
565					case 'date':
566						aVal = a.date || '';
567						bVal = b.date || '';
568						break;
569					case 'vendor':
570						aVal = a.vendor || '';
571						bVal = b.vendor || '';
572						break;
573					case 'amount':
574						aVal = a.amount || 0;
575						bVal = b.amount || 0;
576						break;
577					case 'creditCard':
578						aVal = a.creditCard || '';
579						bVal = b.creditCard || '';
580						break;
581					case 'matchStatus': {
582						const statusOrder = { matched: 0, unmatchedReceipt: 1, unmatchedTransaction: 2 };
583						aVal = statusOrder[a.type];
584						bVal = statusOrder[b.type];
585						break;
586					}
587					default:
588						return 0;
589				}
590	
591				if (typeof aVal === 'string') {
592					return direction * aVal.localeCompare(bVal as string);
593				} else {
594					return direction * (aVal - (bVal as number));
595				}
596			});
597	
598			return sortedRows;
599		}
600	}
