1	// Reconciliation models for matching receipts with transactions
2	
3	import type { ReceiptRow } from './Receipt';
4	import type { TransactionRow } from './Transaction';
5	
6	/**
7	 * Confidence level assigned to a receipt/transaction match
8	 */
9	export type MatchConfidence = 'high' | 'medium' | 'low';
10	
11	/**
12	 * Tolerances used by the matching algorithm when comparing receipts to transactions
13	 */
14	export type MatchingTolerances = {
15		maxDaysDifference: number; // Max days between receipt and transaction dates
16		amountTolerance: number; // Max absolute CAD difference for same-currency matches
17		foreignCurrencyTolerancePercent: number; // #{#fcr3a} Max relative difference for converted amounts
18	};
19	
20	/**
21	 * Single source of truth for the matching tolerance defaults
22	 */
23	export const DEFAULT_MATCHING_TOLERANCES: MatchingTolerances = {
24		maxDaysDifference: 3,
25		amountTolerance: 0.01, // 1 cent
26		foreignCurrencyTolerancePercent: 0.05 // 5%
27	};
28	
29	/**
30	 * Fills any missing tolerance overrides with the defaults
31	 */
32	export function resolveMatchingTolerances(
33		overrides: Partial<MatchingTolerances>
34	): MatchingTolerances {
35		return {
36			maxDaysDifference: overrides.maxDaysDifference ?? DEFAULT_MATCHING_TOLERANCES.maxDaysDifference,
37			amountTolerance: overrides.amountTolerance ?? DEFAULT_MATCHING_TOLERANCES.amountTolerance,
38			foreignCurrencyTolerancePercent:
39				overrides.foreignCurrencyTolerancePercent ??
40				DEFAULT_MATCHING_TOLERANCES.foreignCurrencyTolerancePercent
41		};
42	}
43	
44	/**
45	 * Represents a matched pair of receipt and transaction
46	 */
47	export type MatchedPair = {
48		receipt: ReceiptRow;
49		transaction: TransactionRow;
50		matchConfidence: MatchConfidence;
51	};
52	
53	/**
54	 * Represents an unmatched receipt (no corresponding transaction found)
55	 */
56	export type UnmatchedReceipt = {
57		receipt: ReceiptRow;
58		potentialMatches: TransactionRow[];
59	};
60	
61	/**
62	 * Represents an unmatched transaction (no corresponding receipt found)
63	 */
64	export type UnmatchedTransaction = {
65		transaction: TransactionRow;
