511		/** Validate the split against the original total and return what remains on the original. */
512		private static computeRemainingAmount(
513			originalAmount: number | null,
514			splitAmount: number
515		): number {
516			if (originalAmount == null || originalAmount <= 0) {
517				throw new Error('Cannot split a receipt with no amount');
518			}
519			const remainingAmount = Math.round((originalAmount - splitAmount) * 100) / 100;
520			if (splitAmount >= originalAmount || remainingAmount <= 0) {
521				throw new Error('Split amount must be less than the receipt total');
522			}
523			return remainingAmount;
524		}
