526		/** The new split inherits the original's identity fields but never its transaction match. */
527		private static buildSplitReceiptInsert(
528			original: ReceiptRow,
529			splitAmount: number,
530			splitDate: string | null | undefined,
531			splitGroupId: string
532		): ReceiptInsert {
533			// #{#spl7a} - Use splitDate if provided, otherwise inherit from original
534			const effectiveDate = splitDate ?? original.transaction_date;
535	
536			// #{#spl7a} #{#spl7c} - Recalculate suspicious_date based on the split's own date
537			const effectiveSuspicious = splitDate ? isSuspiciousDate(splitDate) : original.suspicious_date;
538	
539			return {
540				receipt_image_path: original.receipt_image_path,
541				transaction_date: effectiveDate,
542				total_amount: splitAmount,
543				tax: null,
544				merchant_name: original.merchant_name,
545				credit_card_name: original.credit_card_name,
546				credit_card_last_4: original.credit_card_last_4,
547				currency: original.currency,
548				matched_transaction_id: null,
549				suspicious_date: effectiveSuspicious,
550				split_group_id: splitGroupId
551			};
552		}
