564		/**
565		 * #{#spl5a} Update the original (reduce amount, set split_group_id, clear match).
566		 * On failure, best-effort delete of the just-inserted split keeps the pair consistent.
567		 */
568		private async reduceOriginalAfterSplitOrRollback(
569			receiptId: string,
570			remainingAmount: number,
571			splitGroupId: string,
572			newReceiptId: string
573		): Promise<ReceiptRow> {
574			const { data: updatedOriginal, error: updateError } = await this.supabase
575				.from('receipts')
576				.update({
577					total_amount: remainingAmount,
578					matched_transaction_id: null,
579					split_group_id: splitGroupId
580				})
581				.eq('id', receiptId)
582				.select('*')
583				.single();
584	
585			if (updateError) {
586				// Rollback: delete the newly created receipt
587				try {
588					await this.supabase.from('receipts').delete().eq('id', newReceiptId);
589				} catch {
590					// Best-effort rollback
591				}
592				throw updateError;
593			}
594	
595			return updatedOriginal as ReceiptRow;
596		}
