598		/**
599		 * #{#blk3a} Bulk delete multiple receipts in a single database operation
600		 * @param receiptIds Array of receipt IDs to delete
601		 * @returns Promise that resolves when deletion is complete
602		 */
603		async bulkDeleteReceipts(receiptIds: string[]): Promise<{ deletedCount: number }> {
604			return withRetry(async () => {
605				// Get authenticated user
606				const user = (await this.supabase.auth.getUser()).data.user;
607				if (!user) throw new Error('Not authenticated');
608	
609				// Delete all receipts in a single query using IN clause
610				// Only delete receipts belonging to the authenticated user
611				const { error } = await this.supabase
612					.from('receipts')
613					.delete()
614					.in('id', receiptIds)
615					.eq('user_id', user.id);
616	
617				if (error) throw error;
618	
619				// Return metadata about deletion
620				return { deletedCount: receiptIds.length };
621			});
622		}
623	}
